package com.greatleyposhley.professy.collaboration;
import com.greatleyposhley.professy.entities.*;import com.greatleyposhley.professy.repositories.UserAccountRepository;
import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import tools.jackson.databind.ObjectMapper;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class RoadmapValidationTest {
 @Test void linkedTicketsCannotComeFromAnotherProject(){var jdbc=mock(JdbcTemplate.class);var access=spy(new WorkAccess(mock(UserAccountRepository.class),jdbc,mock(WorkspacePolicy.class)));var actor=new UserAccount();actor.setId(3L);actor.setOrgId(7L);doReturn(actor).when(access).actor();doNothing().when(access).project(10);doReturn(Map.of("work_project_id",20L)).when(access).ticket("EPIC",5,false);var controller=new RoadmapController(access,new ObjectMapper());assertThrows(IllegalArgumentException.class,()->controller.create(Map.of("projectId",10,"title","Outcome","startsOn","2027-01-01","targetOn","2027-03-01","tickets",List.of(Map.of("kind","EPIC","id",5)))));verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void targetCannotPrecedeStart(){var access=mock(WorkAccess.class);var actor=new UserAccount();actor.setId(3L);actor.setOrgId(7L);when(access.actor()).thenReturn(actor);var controller=new RoadmapController(access,new ObjectMapper());assertThrows(IllegalArgumentException.class,()->controller.create(Map.of("projectId",10,"title","Outcome","startsOn","2027-03-01","targetOn","2027-01-01","tickets",List.of())));}
}
